// ---- the text form (docs/SPEC-TABLES.md §16) ----
//
// One table, one text, one walk over the reflection descriptors. These are
// the per-table entry points; the walk itself lives once in the shared
// runtime, which is what makes the text form schema's rather than a
// packer's (§16.1).

// table_entity_from_json fills one caller-owned TableEntity from the §16 text, reporting every
// tolerance event. Unknown keys skip, a duplicate key is last-wins, a key
// with the wrong JSON type is skipped and counted, never coerced.
pub fn table_entity_from_json(value: &mut TableEntity, text: &[u8], report: &mut TableReport) -> bool {
    unsafe {
        table_json_read(value as *mut TableEntity as *mut u8, table_entity_table_type(), text, report)
    }
}

// table_entity_to_json_measure is the exact byte length table_entity_to_json writes — the wire's
// measure/write symmetry, carried into the text form.
pub fn table_entity_to_json_measure(value: &TableEntity) -> i64 {
    unsafe {
        table_json_write(value as *const TableEntity as *const u8, table_entity_table_type(), None)
    }
}

pub fn table_entity_to_json(value: &TableEntity, buffer: &mut [u8]) -> i64 {
    unsafe {
        table_json_write(value as *const TableEntity as *const u8, table_entity_table_type(), Some(buffer))
    }
}

